def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return 0, 0
        return 0, 0

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for t in targets:
            tx, ty = pos(t)
            d = abs(tx - sx) + abs(ty - sy)
            if best is None or d < best_d:
                best = (tx, ty)
                best_d = d
        return best

    def farthest(targets, sx, sy):
        best = None
        best_d = None
        for t in targets:
            tx, ty = pos(t)
            d = abs(tx - sx) + abs(ty - sy)
            if best is None or d > best_d:
                best = (tx, ty)
                best_d = d
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))

    def step_toward(tx, ty):
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def step_away(tx, ty):
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(ox, oy)
        w = observation.get("grid_width", 0)
        h = observation.get("grid_height", 0)
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        target = farthest(corners, ox, oy) if corners else None
        if target is not None:
            return step_toward(target[0], target[1])
        return step_away(ox, oy)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        target = nearest(targets, sx, sy)
        if target is not None:
            return step_toward(target[0], target[1])
        return step_away(ox, oy)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = nearest(resources, sx, sy)
    if target is not None:
        return step_toward(target[0], target[1])

    if ox != sx or oy != sy:
        return step_away(ox, oy)
    return [0, 0]

